{"command":"cat <<'PY' > /tmp/find_symbols.py
import subprocess, concurrent.futures, sys
words=open("/tmp/words2.txt").read().split()
# perhaps exclude known
known={"start","end","char","space","whitespace","digit","word","alphabetic","alphanumeric","tab","vertical","newline","feed","return","backspace","null","boundary"}
words=[w for w in words if w not in known]
print("testing",len(words),flush=True)
def test(w):
    p=subprocess.run(["./executable","-"],input=f"<{w}>;".encode(),capture_output=True)
    if p.returncode==0:
        return (w,p.stdout)
    return None

with open("/tmp/found_symbols.txt","w") as out:
    with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
        for i,res in enumerate(ex.map(test, words, chunksize=20)):
            if res:
                out.write(repr(res)+"\n"); out.flush()
                print("FOUND",res,flush=True)
            if i%5000==0:
                print(i,flush=True)
print("done")
