import os, pty, subprocess, select, time, sys
class Repl:
    def __init__(self, args=["./executable","-r"], env=None):
        self.master,self.slave=pty.openpty()
        # set winsize maybe
        import fcntl, termios, struct
        fcntl.ioctl(self.slave, termios.TIOCSWINSZ, struct.pack("HHHH", 50, 120, 0,0))
        e=dict(os.environ); e["TERM"]="xterm-256color"
        if env:
            for k,v in env.items():
                if v is None: e.pop(k,None)
                else: e[k]=v
        self.proc=subprocess.Popen(args, stdin=self.slave, stdout=self.slave, stderr=self.slave, env=e, close_fds=True)
        os.close(self.slave)
        os.set_blocking(self.master, False)
    def read_avail(self, timeout=0.4):
        out=b""
        end=time.time()+timeout
        while time.time()<end:
            r,_,_=select.select([self.master],[],[],0.05)
            if r:
                try:
                    data=os.read(self.master, 65536)
                except OSError as ex:
                    out+=f"<OSError {ex}>".encode(); break
                if not data: break
                out+=data
                end=time.time()+0.2
            if self.proc.poll() is not None:
                # drain
                r,_,_=select.select([self.master],[],[],0.1)
                if not r: break
        return out
    def send(self, s):
        if isinstance(s,str): s=s.encode()
        os.write(self.master,s)
    def line(self,s):
        self.send(s+"\r")
        time.sleep(0.05)
        return self.read_avail(0.5)
    def close(self):
        try: os.close(self.master)
        except: pass

if __name__=="__main__":
    r=Repl()
    print("START", repr(r.read_avail(0.8)))
    for s in ['"#";','some of <word>;', '"abc";', ':s', ':u', ':s', ':r', ':s', '', '   ', 'match {', '"a";','}', ':s']:
