        print(f">>> {s!r}\n{out!r}\n---decoded---\n{out.decode(errors='replace')}\n=====")
    out=r.line(':e')
    print("EXITLINE", out, "poll", r.proc.poll())
    time.sleep(0.3); print("poll", r.proc.poll(), "more", r.read_avail(0.3))
