{"command":"cat <<'EOF' > src/compiler.rs
use pest::iterators::Pair;
use pest::Parser;
use pest_derive::Parser;
use std::collections::HashMap;

#[derive(Parser)]
#[grammar = "melody.pest"]
struct MelodyParser;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum NodeKind {
    Normal,
    SpecialSymbol,
    Assertion,
    VariableInvocation,
    Skipped,
}

#[derive(Clone, Debug)]
struct Node {
    text: String,
    kind: NodeKind,
}

impl Node {
    fn normal(text: String) -> Self {
        Node {
            text,
            kind: NodeKind::Normal,
        }
    }
}

pub fn compile(source: &str) -> Result<String, String> {
    let processed = preprocess(source);
    let mut pairs = MelodyParser::parse(Rule::root, &processed).map_err(|error| error.to_string())?;
    let root = pairs.next().unwrap();
    let mut variables: HashMap<String, String> = HashMap::new();
    let nodes = generate_body(root, &mut variables)?;
    Ok(nodes.iter().map(|node| node.text.as_str()).collect::<String>())
}

fn preprocess(source: &str) -> String {
    source
        .lines()
        .map(|line| {
            let trimmed_start = line.trim_start();
            if trimmed_start.starts_with("//") {
                format!("/*{}*/", trimmed_start.trim_start_matches("//"))
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<String>>()
        .join("\n")
}

fn generate_body(pair: Pair<'_, Rule>, variables: &mut HashMap<String, String>) -> Result<Vec<Node>, String> {
    let mut nodes = Vec::new();
    let mut inner = pair.into_inner().peekable();
    while let Some(child) = inner.next() {
        match child.as_rule() {
            Rule::EOI => {}
            Rule::quantifier_quantity => {
                let operand_pair = inner.next().expect("quantifier without a following expression");
                let operand = generate_node(operand_pair, variables)?;
                match operand.kind {
                    NodeKind::SpecialSymbol => {
                        return Err("unexpected special symbol in quantifier".to_string())
                    }
                    NodeKind::Assertion => {
                        return Err("unexpected assertion in quantifier".to_string())
                    }
                    NodeKind::VariableInvocation => {
                        return Err("unexpected variable invocation in quantifier".to_string())
                    }
                    NodeKind::Skipped => {
                        return Err("unexpected skipped node in quantifier".to_string())
                    }
                    NodeKind::Normal => {}
                }
                let suffix = generate_quantifier_quantity(child)?;
                let wrapped = wrap_for_quantifier(&operand.text);
                nodes.push(Node::normal(format!("{}{}", wrapped, suffix)));
            }
            _ => nodes.push(generate_node(child, variables)?),
        }
    }
    Ok(nodes)
}

fn concat_body(pair: Pair<'_, Rule>, variables: &mut HashMap<String, String>) -> Result<String, String> {
    let nodes = generate_body(pair, variables)?;
    Ok(nodes.iter().map(|node| node.text.as_str()).collect::<String>())
}

fn generate_node(pair: Pair<'_, Rule>, variables: &mut HashMap<String, String>) -> Result<Node, String> {
    match pair.as_rule() {
        Rule::literal => Ok(Node::normal(transform_literal(pair.as_str()))),
        Rule::symbol_identifier => {
            let (text, kind) = symbol_positive(pair.as_str().trim())?;
            Ok(Node {
                text: text.to_string(),
                kind,
            })
        }
        Rule::raw => Ok(Node::normal(transform_raw(pair.as_str()))),
        Rule::range => Ok(Node::normal(generate_range(pair))),
        Rule::not => generate_not(pair),
        Rule::group_declaration => generate_group(pair, variables),
        Rule::assertion_declaration => generate_assertion(pair, variables),
        Rule::variable_declaration => generate_variable_declaration(pair, variables),
        Rule::variable_invocation => {
            let mut inner = pair.into_inner();
            let identifier = inner.next().expect("variable invocation without identifier");
            let name = identifier.as_str().to_string();
            let text = variables
                .get(&name)
                .cloned()
                .ok_or_else(|| "usage of an uninitialized variable".to_string())?;
            Ok(Node {
                text,
                kind: NodeKind::VariableInvocation,
            })
        }
        Rule::EOI => Ok(Node::normal(String::new())),
        other => panic!("unexpected rule in generation: {:?}", other),
    }
}

fn generate_group(pair: Pair<'_, Rule>, variables: &mut HashMap<String, String>) -> Result<Node, String> {
    let pair_text = pair.as_str().to_string();
    let mut capture_name: Option<String> = None;
    let mut block: Option<Pair<'_, Rule>> = None;
    for child in pair.into_inner() {
        match child.as_rule() {
            Rule::identifier => capture_name = Some(child.as_str().trim().to_string()),
            Rule::block => block = Some(child),
            _ => {}
        }
    }
    let block = block.expect("group without block");
    if pair_text.starts_with("either") {
        let nodes = generate_body(block, variables)?;
        let alternatives = nodes
            .iter()
            .map(|node| node.text.as_str())
            .collect::<Vec<&str>>()
            .join("|");
        Ok(Node::normal(format!("(?:{})", alternatives)))
    } else if pair_text.starts_with("capture") {
        let contents = concat_body(block, variables)?;
        if let Some(name) = capture_name {
            Ok(Node::normal(format!("(?<{}>{})", name, contents)))
        } else {
            Ok(Node::normal(format!("({})", contents)))
        }
    } else {
        let contents = concat_body(block, variables)?;
        Ok(Node::normal(format!("(?:{})", contents)))
    }
}

fn generate_assertion(pair: Pair<'_, Rule>, variables: &mut HashMap<String, String>) -> Result<Node, String> {
    let negated = pair.as_str().starts_with("not");
    let mut assertion_type = "";
    let mut block: Option<Pair<'_, Rule>> = None;
    for child in pair.into_inner() {
        match child.as_rule() {
            Rule::assertion_type => assertion_type = child.as_str(),
            Rule::block => block = Some(child),
            _ => {}
        }
    }
    let contents = concat_body(block.expect("assertion without block"), variables)?;
    let text = match (assertion_type, negated) {
        ("ahead", false) => format!("(?={})", contents),
        ("ahead", true) => format!("(?!{})", contents),
        ("behind", false) => format!("(?<={})", contents),
        ("behind", true) => format!("(?<!{})", contents),
        _ => panic!("unexpected assertion type"),
    };
    Ok(Node {
        text,
        kind: NodeKind::Assertion,
    })
}

fn generate_variable_declaration(
    pair: Pair<'_, Rule>,
    variables: &mut HashMap<String, String>,
) -> Result<Node, String> {
    let mut name = String::new();
    let mut block: Option<Pair<'_, Rule>> = None;
    for child in pair.into_inner() {
        match child.as_rule() {
            Rule::identifier => name = child.as_str().trim().to_string(),
            Rule::block => block = Some(child),
            _ => {}
        }
    }
    let contents = concat_body(block.expect("variable declaration without block"), variables)?;
    variables.insert(name, contents);
    Ok(Node {
        text: String::new(),
        kind: NodeKind::Skipped,
    })
}

fn generate_range(pair: Pair<'_, Rule>) -> String {
    let mut inner = pair.into_inner();
    let first = inner.next().expect("range without start");
    let second = inner.next().expect("range without end");
    let start = first.as_str().chars().next().expect("range with empty start");
    let end = second.as_str().chars().next().expect("range with empty end");
    format!("[{}-{}]", start, end)
}

fn generate_not(pair: Pair<'_, Rule>) -> Result<Node, String> {
    let child = pair
        .into_inner()
        .next()
        .expect("not expression without an operand");
    match child.as_rule() {
        Rule::range => {
            let range = generate_range(child);
            Ok(Node::normal(format!("[^{}]", &range[1..range.len() - 1])))
        }
        Rule::class_content => Ok(Node::normal(format!("[^{}]", child.as_str()))),
        Rule::symbol_identifier => {
            let text = symbol_negative(child.as_str().trim())?;
            Ok(Node::normal(text.to_string()))
        }
        other => panic!("unexpected rule in not expression: {:?}", other),
    }
}

fn generate_quantifier_quantity(pair: Pair<'_, Rule>) -> Result<String, String> {
    let lazy = pair.as_str().starts_with("lazy");
    let children: Vec<Pair<'_, Rule>> = pair.into_inner().collect();
    let mut suffix: String;
    if let Some(_some) = children.iter().find(|child| child.as_rule() == Rule::some) {
        suffix = "+".to_string();
    } else if let Some(_any) = children.iter().find(|child| child.as_rule() == Rule::any) {
        suffix = "*".to_string();
    } else if let Some(_option) = children.iter().find(|child| child.as_rule() == Rule::option) {
        suffix = "?".to_string();
    } else if let Some(over) = children.iter().find(|child| child.as_rule() == Rule::over) {
        let amount_text = over
            .clone()
            .into_inner()
            .next()
            .expect("over quantifier without amount")
            .as_str()
            .to_string();
        let amount = amount_text
            .parse::<u64>()
            .ok()
            .and_then(|value| value.checked_add(1))
            .ok_or_else(|| "could not parse an amount".to_string())?;
        suffix = format!("{{{},}}", amount);
    } else {
        let amounts: Vec<&str> = children
            .iter()
            .filter(|child| child.as_rule() == Rule::amount)
            .map(|child| child.as_str())
            .collect();
        if amounts.len() == 1 {
            suffix = format!("{{{}}}", amounts[0]);
        } else if amounts.len() == 2 {
            let first = amounts[0].parse::<u64>();
            let second = amounts[1].parse::<u64>();
            if !matches!((first, second), (Ok(first_value), Ok(second_value)) if first_value <= second_value) {
                return Err("usage of an invalid quantifier range".to_string());
            }
            suffix = format!("{{{}, {}}}", amounts[0], amounts[1]);
            // The formatted value above is corrected below; quantifier ranges have no spaces.
            suffix = format!("{{{}, {}}}", amounts[0], amounts[1]).replace(", ", ",");
        } else {
            panic!("quantifier quantity without a recognized form");
        }
    }
    if lazy {
        suffix.push('?');
    }
    Ok(suffix)
}

fn wrap_for_quantifier(text: &str) -> String {
    let count = text.chars().count();
    let unwrapped = count == 1
        || (count == 2 && text.starts_with('\\'))
        || (count > 2
            && ((text.starts_with('(') && text.ends_with(')'))
                || (text.starts_with('[') && text.ends_with(']'))));
    if unwrapped {
        text.to_string()
    } else {
        format!("(?:{})", text)
    }
}

fn symbol_positive(name: &str) -> Result<(&'static str, NodeKind), String> {
    let result = match name {
        "start" => ("^", NodeKind::SpecialSymbol),
        "end" => ("$", NodeKind::SpecialSymbol),
        "char" => (".", NodeKind::Normal),
        "space" => (" ", NodeKind::Normal),
        "whitespace" => ("\\s", NodeKind::Normal),
        "digit" => ("\\d", NodeKind::Normal),
        "word" => ("\\w", NodeKind::Normal),
        "alphabetic" => ("[a-zA-Z]", NodeKind::Normal),
        "alphanumeric" => ("[a-zA-Z0-9]", NodeKind::Normal),
        "tab" => ("\\t", NodeKind::Normal),
        "vertical" => ("\\v", NodeKind::Normal),
        "newline" => ("\\n", NodeKind::Normal),
        "feed" => ("\\f", NodeKind::Normal),
        "return" => ("\\r", NodeKind::Normal),
        "backspace" => ("[\\b]", NodeKind::Normal),
        "null" => ("\\0", NodeKind::Normal),
        "boundary" => ("\\b", NodeKind::Normal),
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(result)
}

fn symbol_negative(name: &str) -> Result<&'static str, String> {
    let result = match name {
        "start" => return Err("negative start not allowed".to_string()),
        "end" => return Err("negative end not allowed".to_string()),
        "char" => return Err("negative char not allowed".to_string()),
        "space" => "[^ ]",
        "whitespace" => "\\S",
        "digit" => "\\D",
        "word" => "\\W",
        "alphabetic" => "[^a-zA-Z]",
        "alphanumeric" => "[^a-zA-Z0-9]",
        "tab" => "[^\\t]",
        "vertical" => "[^\\v]",
        "newline" => "[^\\n]",
        "feed" => "[^\\f]",
        "return" => "[^\\r]",
        "backspace" => "[^\\b]",
        "null" => "[^\\0]",
        "boundary" => "\\B",
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(result)
}

fn transform_literal(text: &str) -> String {
    let quote = text.chars().next().expect("empty literal");
    let inner = &text[1..text.len() - 1];
    let chars: Vec<char> = inner.chars().collect();
    let mut result = String::new();
    let mut index = 0;
    while index < chars.len() {
        let current = chars[index];
        if current == '\\' {
            let next = chars[index + 1];
            if next == quote {
                result.push(quote);
                index += 2;
            } else if next == 'u' {
                result.push('\\');
                result.push('u');
                for offset in 0..4 {
                    result.push(chars[index + 2 + offset]);
                }
                index += 6;
            } else {
                result.push('\\');
                result.push(next);
                index += 2;
            }
        } else if ".*+?^${}()|[]\\".contains(current) {
            result.push('\\');
            result.push(current);
            index += 1;
        } else {
            result.push(current);
            index += 1;
        }
    }
    result
}

fn transform_raw(text: &str) -> String {
    let inner = &text[1..text.len() - 1];
    let chars: Vec<char> = inner.chars().collect();
    let mut result = String::new();
    let mut index = 0;
    while index < chars.len() {
        let current = chars[index];
        if current == '\\' {
            let next = chars[index + 1];
            if next == '`' {
                result.push('`');
            } else {
                result.push('\\');
                result.push(next);
            }
            index += 2;
        } else {
            result.push(current);
            index += 1;
        }
    }
    result
}
EOF
"}

