        "start" => ("^", NodeKind::SpecialSymbol),
        "end" => ("$", NodeKind::SpecialSymbol),
        "char" => (".", NodeKind::Normal),
        "space" => (" ", NodeKind::Normal),
        "whitespace" => ("\\s", NodeKind::Normal),
        "digit" => ("\\d", NodeKind::Normal),
        "word" => ("\\w", NodeKind::Normal),
        "alphabetic" => ("[a-zA-Z]", NodeKind::Normal),
        "alphanumeric" => ("[a-zA-Z0-9]", NodeKind::Normal),
        "tab" => ("\\t", NodeKind::Normal),
        "vertical" => ("\\v", NodeKind::Normal),
        "newline" => ("\\n", NodeKind::Normal),
        "feed" => ("\\f", NodeKind::Normal),
        "return" => ("\\r", NodeKind::Normal),
        "backspace" => ("[\\b]", NodeKind::Normal),
        "null" => ("\\0", NodeKind::Normal),
        "boundary" => ("\\b", NodeKind::Normal),
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(result)
}

fn symbol_negative(name: &str) -> Result<&'static str, String> {
    let result = match name {
        "start" => return Err("negative start not allowed".to_string()),
        "end" => return Err("negative end not allowed".to_string()),
        "char" => return Err("negative char not allowed".to_string()),
        "space" => "[^ ]",
        "whitespace" => "\\S",
        "digit" => "\\D",
        "word" => "\\W",
        "alphabetic" => "[^a-zA-Z]",
        "alphanumeric" => "[^a-zA-Z0-9]",
        "tab" => "[^\\t]",
        "vertical" => "[^\\v]",
        "newline" => "[^\\n]",
        "feed" => "[^\\f]",
        "return" => "[^\\r]",
        "backspace" => "[^\\b]",
        "null" => "[^\\0]",
        "boundary" => "\\B",
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(result)
}

fn transform_literal(text: &str) -> String {
    let quote = text.chars().next().expect("empty literal");
    let inner = &text[1..text.len() - 1];
    let chars: Vec<char> = inner.chars().collect();
    let mut result = String::new();
    let mut index = 0;
    while index < chars.len() {
        let current = chars[index];
        if current == '\\' {
            let next = chars[index + 1];
            if next == quote {
                result.push(quote);
                index += 2;
            } else if next == 'u' {
                result.push('\\');
                result.push('u');
                for offset in 0..4 {
                    result.push(chars[index + 2 + offset]);
                }
                index += 6;
            } else {
                result.push('\\');
                result.push(next);
                index += 2;
            }
        } else if ".*+?^${}()|[]\\".contains(current) {
            result.push('\\');
            result.push(current);
            index += 1;
        } else {
            result.push(current);
            index += 1;
        }
    }
    result
}

fn transform_raw(text: &str) -> String {
    let inner = &text[1..text.len() - 1];
    let chars: Vec<char> = inner.chars().collect();
    let mut result = String::new();
    let mut index = 0;
    while index < chars.len() {
        let current = chars[index];
        if current == '\\' {
            let next = chars[index + 1];
            if next == '`' {
                result.push('`');
            } else {
                result.push('\\');
                result.push(next);
            }
            index += 2;
        } else {
            result.push(current);
            index += 1;
        }
    }
    result
}
