        format!("{}...", test.chars().take(10).collect::<String>())
    } else {
        test.to_string()
    }
}

fn regex_matches(pattern: &str, text: &str) -> Result<bool, String> {
    let regex = fancy_regex::Regex::new(pattern)
        .map_err(|error| format!("could not compile regex\nCause: {}\nRegex: {}", error, pattern))?;
    Ok(regex.is_match(text).unwrap_or(false))
}

fn repl() -> Result<(), String> {
    println!(
        "{}",
        bright_green(&format!("Melody REPL v{}", env!("CARGO_PKG_VERSION")))
    );
    println!();
    println!("{}", bright_green("Commands:"));
    println!();
    println!(
        "- {} - {}",
        bright_blue(":u, :undo"),
        bright_green("undo the latest line")
    );
    println!(
        "- {} - {}",
        bright_blue(":r, :redo"),
        bright_green("redo the latest undo")
    );
    println!(
        "- {} - {}",
        bright_blue(":c, :clear"),
        bright_green("clear all REPL history and previous input")
    );
    println!(
        "- {} - {}",
        bright_blue(":s, :source"),
        bright_green("print all previously entered lines")
    );
    println!(
        "- {} - {}",
        bright_blue(":e, :exit"),
        bright_green("exit the REPL")
    );
    println!();

    let stdin = io::stdin();
    let mut lines: Vec<String> = Vec::new();
    let mut undone_lines: Vec<String> = Vec::new();

    loop {
        print!("{}", bright_blue("~ "));
        io::stdout()
            .flush()
            .map_err(|_| "unable to read input".to_string())?;

        let mut raw_line = String::new();
        stdin
            .read_line(&mut raw_line)
            .map_err(|_| "unable to read input".to_string())?;
        let line = raw_line.trim_end().to_string();

        if line.starts_with(':') {
            match line.as_str() {
                ":u" | ":undo" => {
                    if let Some(undone) = lines.pop() {
                        undone_lines.push(undone);
                        println!("{}", bright_green("undo"));
                        let compiled = compiler::compile(&lines.join("\n")).unwrap_or_default();
                        println!("{}\n", bright_blue(&compiled));
                    } else {
                        println!("{}", bright_red("nothing to undo\n"));
                    }
                }
                ":r" | ":redo" => {
                    if let Some(redone) = undone_lines.pop() {
                        lines.push(redone);
                        println!("{}", bright_green("redo"));
                        let compiled = compiler::compile(&lines.join("\n")).unwrap_or_default();
                        println!("{}\n", bright_blue(&compiled));
                    } else {
                        println!("{}", bright_red("nothing to redo\n"));
                    }
                }
                ":c" | ":clear" => {
                    lines.clear();
                    undone_lines.clear();
                    println!("{}\n", bright_green("clear"));
                }
                ":s" | ":source" => {
                    if lines.is_empty() {
                        println!("{}", bright_red("no lines to print\n"));
                    } else {
                        println!("{}", bright_green("source"));
                        for (index, source_line) in lines.iter().enumerate() {
                            println!(
                                "{} {}",
                                dimmed(&(index + 1).to_string()),
                                bright_blue(source_line)
                            );
                        }
                        println!();
                    }
                }
                ":e" | ":exit" => {
                    println!("{}", bright_green("exit"));
                    return Ok(());
                }
                _ => {
                    println!(
                        "{} {} {}",
                        bright_red("Error:"),
                        bright_red("unrecognized command"),
                        bright_blue(&format!("\"{}\"", line))
                    );
                    println!();
                }
            }
            continue;
        }

        if line.is_empty() {
            let compiled = compiler::compile(&lines.join("\n")).unwrap_or_default();
            println!("{}\n", bright_blue(&compiled));
            continue;
        }

        lines.push(line);
        match compiler::compile(&lines.join("\n")) {
            Ok(compiled) => {
                undone_lines.clear();
                println!("{}\n", bright_blue(&compiled));
            }
            Err(message) => {
                lines.pop();
                println!("{}\n", bright_red(&format!("Error: {}", message)));
            }
        }
    }
}

