import re, ast, collections
patterns=collections.Counter(); examples={}
for fn in ['/tmp/diff_atoms.txt','/tmp/diff_basic.txt']:
 text=open(fn).read(); chunks=re.split(r'(?m)^DIFF ',text)[1:]
 for c in chunks:
  vals=[]
  for l in c.splitlines():
   ls=l.strip()
   if ls.startswith('orig=') or ls.startswith('ours='):
    vals.append(ast.literal_eval(ls[5:]))
  if len(vals)!=2: continue
  def getlist(stderr):
   m=re.search(rb'= expected ([^\n]*)',stderr)
   if not m: return ()
   s=m.group(1).decode()
   # split commas/or
   parts=re.split(r',\s*|\s+or\s+',s)
   return tuple(parts)
  a=getlist(vals[0][2]); b=getlist(vals[1][2])
  key=(a,b); patterns[key]+=1; examples.setdefault(key,c.splitlines()[0])
for (a,b),n in patterns.most_common():
 print(f"{n}: orig={a}\n   ours={b}\n   ex={examples[(a,b)]}\n")
PY"}

