new_quantity='''fn generate_quantifier_quantity(pair: Pair<'_, Rule>) -> Result<String, String> {
    let lazy = pair.as_str().starts_with("lazy");
    let children: Vec<Pair<'_, Rule>> = pair.into_inner().collect();
    let mut suffix: String;
    if children.iter().any(|child| child.as_rule() == Rule::some) {
        suffix = "+".to_string();
    } else if children.iter().any(|child| child.as_rule() == Rule::any) {
        suffix = "*".to_string();
    } else if children.iter().any(|child| child.as_rule() == Rule::option) {
        suffix = "?".to_string();
    } else if children.iter().any(|child| child.as_rule() == Rule::over) {
        let amount_text = children
            .iter()
            .find(|child| child.as_rule() == Rule::amount)
            .expect("over quantifier without amount")
            .as_str();
        let amount = amount_text
            .parse::<u64>()
            .ok()
            .and_then(|value| value.checked_add(1))
            .ok_or_else(|| "could not parse an amount".to_string())?;
        suffix = format!("{{{},}}", amount);
    } else if let Some(range) = children
        .iter()
        .find(|child| child.as_rule() == Rule::quantifier_range)
    {
        let amounts: Vec<&str> = range.clone().into_inner().map(|amount| amount.as_str()).collect();
        let first = amounts[0].parse::<u64>();
        let second = amounts[1].parse::<u64>();
        if !matches!((first, second), (Ok(first_value), Ok(second_value)) if first_value <= second_value) {
            return Err("usage of an invalid quantifier range".to_string());
        }
        suffix = format!("{{{}, {}}}", amounts[0], amounts[1]).replace(", ", ",");
    } else {
        let amount_text = children
            .iter()
            .find(|child| child.as_rule() == Rule::amount)
            .expect("quantifier quantity without a recognized form")
            .as_str();
        suffix = format!("{{{}}}", amount_text);
    }
    if lazy {
        suffix.push('?');
    }
    Ok(suffix)
}

'''
s=s[:start]+new_quantity+s[end:]
open(p,'w').write(s)
