{"command":"cat <<'EOF' > src/melody.pest
WHITESPACE = _{ " " | "\t" | "\n" }
COMMENT = _{ "/*" ~ (!"*/" ~ ANY)* ~ "*/" }

root = { SOI ~ statement* ~ EOI }

block = { "{" ~ statement+ ~ "}" }

amount = @{ ASCII_DIGIT+ }

some = @{ "some" }
any = @{ "any" }
option = @{ "option" }
over = @{ "over" }

literal = @{ ("\"" ~ (("\\" ~ ("b" | "f" | "n" | "r" | "t" | "/" | "\\" | "\"" | ("u" ~ ASCII_HEX_DIGIT{4}))) | (!("\"" | "\\") ~ ANY))* ~ "\"") | ("'" ~ (("\\" ~ ("b" | "f" | "n" | "r" | "t" | "/" | "\\" | "'" | ("u" ~ ASCII_HEX_DIGIT{4}))) | (!("'" | "\\") ~ ANY))* ~ "'") }

raw = @{ "`" ~ (("\\" ~ ("`" | "\\")) | (!("`" | "\\") ~ ANY))* ~ "`" }

not = { "not" ~ (quantifier_range | (ascii_range_start ~ "to" ~ ascii_range_end) | class_content | ("<" ~ symbol_identifier ~ ">")) }

range = { quantifier_range | (ascii_range_start ~ "to" ~ ascii_range_end) }

quantifier_range = { amount ~ "to" ~ amount }

quantifier_quantity = { ("lazy")? ~ (quantifier_range | amount | some | any | option | (over ~ amount)) }

group_declaration = { ("match" ~ block) | ("either" ~ block) | ("capture" ~ identifier? ~ block) }

assertion_declaration = { ("not")? ~ assertion_type ~ block }

variable_declaration = { "let" ~ "." ~ identifier ~ "=" ~ block }

variable_invocation = { "." ~ identifier }

class_content = { (ASCII_ALPHANUMERIC | "_" | "!" | "@" | "#" | "$" | "%" | "^" | "&" | "*" | "\\")+ }

ascii_range_start = { ASCII }
ascii_range_end = { ASCII }

assertion_type = @{ "ahead" | "behind" }

identifier = { (ASCII_ALPHA | "_")+ }
symbol_identifier = { (ASCII_ALPHA | "_")+ }

statement = _{
    quantifier_quantity ~ "of" ~ (group_declaration | assertion_declaration | variable_declaration) |
    quantifier_quantity ~ "of" ~ simple_expression ~ ";" |
    group_declaration |
    assertion_declaration |
    variable_declaration |
    simple_expression ~ ";"
}

simple_expression = _{
    literal |
    range |
    raw |
    not |
    variable_invocation |
    ("<" ~ symbol_identifier ~ ">")
}
EOF
python3 << 'PY'
p='src/compiler.rs'; s=open(p).read()
old=s[s.index('fn generate_not'):s.index('fn generate_quantifier_quantity')]
new='''fn generate_not(pair: Pair<'_, Rule>) -> Result<Node, String> {
    let mut inner = pair.into_inner();
    let child = inner
        .next()
        .expect("not expression without an operand");
    match child.as_rule() {
        Rule::quantifier_range => {
            let endpoints: Vec<String> = child
                .into_inner()
                .map(|amount| amount.as_str().to_string())
                .collect();
            let start = endpoints[0].chars().next().expect("range with empty start");
            let end = endpoints[1].chars().next().expect("range with empty end");
            Ok(Node::normal(format!("[^{}-{}]", start, end)))
        }
        Rule::ascii_range_start => {
            let start = child.as_str().chars().next().expect("range with empty start");
            let end_pair = inner.next().expect("range without end");
            let end = end_pair
                .as_str()
                .chars()
                .next()
                .expect("range with empty end");
            Ok(Node::normal(format!("[^{}-{}]", start, end)))
        }
        Rule::range => {
            let range = generate_range(child);
            Ok(Node::normal(format!("[^{}]", &range[1..range.len() - 1])))
        }
        Rule::class_content => Ok(Node::normal(format!("[^{}]", child.as_str()))),
        Rule::symbol_identifier => {
            let text = symbol_negative(child.as_str().trim())?;
            Ok(Node::normal(text.to_string()))
        }
        other => panic!("unexpected rule in not expression: {:?}", other),
    }
}

'''
s=s.replace(old,new)
open(p,'w').write(s)
PY
