{"command":"sed -i 's/^symbol_identifier = { (ASCII_ALPHA | "_")+ }$/symbol_identifier = { (ASCII_ALPHA | "_" | ":")+ }/' src/melody.pest
python3 << 'PY'
p='src/compiler.rs'; s=open(p).read()
s=s.replace('''enum NodeKind {
    Normal,''','''enum NodeKind {
    Normal,
    Symbol,''')
# Quantifier match: insert Symbol in allowed? Existing match has exhaustive arms including Normal => {} . Add Symbol alongside Normal.
s=s.replace('''                    NodeKind::Normal => {}''','''                    NodeKind::Normal | NodeKind::Symbol => {}''')
# Wrap logic call: currently let wrapped=wrap_for_quantifier(&operand.text); change based on kind
s=s.replace('''                let wrapped = wrap_for_quantifier(&operand.text);''','''                let wrapped = if operand.kind == NodeKind::Symbol {
                    operand.text.clone()
                } else {
                    wrap_for_quantifier(&operand.text)
                };''')
# Symbol positive generation calls symbol_positive returning kind; we'll replace functions.
start=s.index('fn symbol_positive')
end=s.index('fn transform_literal')
new='''fn symbol_positive(name: &str) -> Result<(String, NodeKind), String> {
    if let Some((namespace, _)) = name.split_once("::") {
        let code = unicode_category_code(name, namespace)?;
        return Ok((format!("\\\\p{{{}}}", code), NodeKind::Symbol));
    }
    let result = match name {
        "start" => ("^", NodeKind::SpecialSymbol),
        "end" => ("$", NodeKind::SpecialSymbol),
        "char" => (".", NodeKind::Symbol),
        "space" => (" ", NodeKind::Symbol),
        "whitespace" => ("\\\\s", NodeKind::Symbol),
        "digit" => ("\\\\d", NodeKind::Symbol),
        "word" => ("\\\\w", NodeKind::Symbol),
        "alphabetic" => ("[a-zA-Z]", NodeKind::Symbol),
        "alphanumeric" => ("[a-zA-Z0-9]", NodeKind::Symbol),
        "tab" => ("\\\\t", NodeKind::Symbol),
        "vertical" => ("\\\\v", NodeKind::Symbol),
        "newline" => ("\\\\n", NodeKind::Symbol),
        "feed" => ("\\\\f", NodeKind::Symbol),
        "return" => ("\\\\r", NodeKind::Symbol),
        "backspace" => ("[\\\\b]", NodeKind::Symbol),
        "null" => ("\\\\0", NodeKind::Symbol),
        "boundary" => ("\\\\b", NodeKind::Symbol),
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok((result.0.to_string(), result.1))
}

fn symbol_negative(name: &str) -> Result<String, String> {
    if let Some((namespace, _)) = name.split_once("::") {
        let code = unicode_category_code(name, namespace)?;
        return Ok(format!("\\\\P{{{}}}", code));
    }
    let result = match name {
        "start" => return Err("negative start not allowed".to_string()),
        "end" => return Err("negative end not allowed".to_string()),
        "char" => return Err("negative char not allowed".to_string()),
        "space" => "[^ ]",
        "whitespace" => "\\\\S",
        "digit" => "\\\\D",
        "word" => "\\\\W",
        "alphabetic" => "[^a-zA-Z]",
        "alphanumeric" => "[^a-zA-Z0-9]",
        "tab" => "[^\\\\t]",
        "vertical" => "[^\\\\v]",
        "newline" => "[^\\\\n]",
        "feed" => "[^\\\\f]",
        "return" => "[^\\\\r]",
        "backspace" => "[^\\\\b]",
        "null" => "[^\\\\0]",
        "boundary" => "\\\\B",
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(result.to_string())
}

fn unicode_category_code(name: &str, namespace: &str) -> Result<&'static str, String> {
    if namespace != "category" {
        return Err("usage of an unrecognized symbol namespace".to_string());
    }
    let category = name.split_once("::").map(|(_, rest)| rest).unwrap_or("");
    let code = match category {
        "letter" => "L",
        "uppercase_letter" => "Lu",
        "lowercase_letter" => "Ll",
        "titlecase_letter" => "Lt",
        "modifier_letter" => "Lm",
        "other_letter" => "Lo",
        "cased_letter" => "L&",
        "mark" => "M",
        "non_spacing_mark" => "Mn",
        "spacing_combining_mark" => "Mc",
        "enclosing_mark" => "Me",
        "number" => "N",
        "decimal_digit_number" => "Nd",
        "letter_number" => "Nl",
        "other_number" => "No",
        "punctuation" => "P",
        "connector_punctuation" => "Pc",
        "dash_punctuation" => "Pd",
        "open_punctuation" => "Ps",
        "close_punctuation" => "Pe",
        "initial_punctuation" => "Pi",
        "final_punctuation" => "Pf",
        "other_punctuation" => "Po",
        "symbol" => "S",
        "math_symbol" => "Sm",
        "currency_symbol" => "Sc",
        "modifier_symbol" => "Sk",
        "other_symbol" => "So",
        "separator" => "Z",
        "space_separator" => "Zs",
        "line_separator" => "Zl",
        "paragraph_separator" => "Zp",
        "other" => "C",
        "control" => "Cc",
        "format" => "Cf",
        "surrogate" => "Cs",
        "private_use" => "Co",
        "unassigned" => "Cn",
        _ => return Err("usage of an unrecognized unicode category".to_string()),
    };
    Ok(code)
}

'''
# In python triple string, \\p etc become \p in file? Need inspect after - format string in Rust should be "\\p{{}}" literal backslash.
s=s[:start]+new+s[end:]
# symbol_positive call site expects (text,kind) and currently does text.to_string(); now text already String, compiler will error calling to_string? String to_string fine.
# generate_not symbol child currently Ok(Node::normal(text.to_string())) where text is String now; Node::normal expects String, text.to_string works but kind Normal not Symbol. Replace that specific construct.
s=s.replace('''        Rule::symbol_identifier => {
            let text = symbol_negative(child.as_str().trim())?;
            Ok(Node::normal(text.to_string()))
        }''','''        Rule::symbol_identifier => {
            let text = symbol_negative(child.as_str().trim())?;
            Ok(Node {
                text,
                kind: NodeKind::Symbol,
            })
        }''')
open(p,'w').write(s)
