use std::collections::HashMap;

pub fn regex_matches(pattern: &str, text: &str) -> Result<bool, String> {
    let mut parser = RegexParser::new(pattern);
    let ast = parser.parse()?;
    let group_count = parser.group_count;
    let input: Vec<char> = text.chars().collect();
    for start in 0..=input.len() {
        let captures = vec![None; group_count + 1];
        if eval(&ast, &input, start, captures, &mut |_, _| true) {
            return Ok(true);
        }
    }
    Ok(false)
}

type Captures = Vec<Option<(usize, usize)>>;

#[derive(Clone, Debug)]
enum Ast {
    Empty,
    Char(u32),
    Dot,
    Class {
        negated: bool,
        items: Vec<ClassItem>,
    },
    Start,
    End,
    WordBoundary {
        negated: bool,
    },
    Sequence(Vec<Ast>),
    Alternation(Vec<Ast>),
    Group {
        capture: Option<usize>,
        child: Box<Ast>,
    },
    Lookahead {
        negated: bool,
        behind: bool,
        child: Box<Ast>,
    },
    Repeat {
        child: Box<Ast>,
        min: u64,
        max: Option<u64>,
        greedy: bool,
    },
    BackReference(usize),
    NamedBackReference(String),
    DecimalEscape {
        digits: String,
        value: u64,
    },
}

#[derive(Clone, Debug)]
enum ClassItem {
    Single(u32),
    Range(u32, u32),
    Digit { negated: bool },
    Word { negated: bool },
    Space { negated: bool },
}

impl ClassItem {
    fn matches(&self, value: u32) -> bool {
        match *self {
            ClassItem::Single(single) => value == single,
            ClassItem::Range(start, end) => (start..=end).contains(&value),
            ClassItem::Digit { negated } => is_ascii_digit(value) != negated,
            ClassItem::Word { negated } => is_word_value(value) != negated,
            ClassItem::Space { negated } => is_space_value(value) != negated,
        }
    }
    fn is_single(&self) -> Option<u32> {
        if let ClassItem::Single(value) = self {
            Some(*value)
        } else {
            None
        }
    }
}

fn eval(
    ast: &Ast,
    input: &[char],
    position: usize,
    captures: Captures,
    continuation: &mut dyn FnMut(usize, Captures) -> bool,
) -> bool {
    match ast {
        Ast::Empty => continuation(position, captures),
        Ast::Char(expected) => {
            if position < input.len() && input[position] as u32 == *expected {
                continuation(position + 1, captures)
            } else {
                false
            }
        }
        Ast::Dot => {
            if position < input.len() && !is_line_terminator(input[position] as u32) {
                continuation(position + 1, captures)
            } else {
                false
            }
        }
        Ast::Class { negated, items } => {
            if position < input.len() {
                let value = input[position] as u32;
                let inside = items.iter().any(|item| item.matches(value));
                if inside != *negated {
                    return continuation(position + 1, captures);
                }
            }
            false
        }
        Ast::Start => position == 0 && continuation(position, captures),
        Ast::End => position == input.len() && continuation(position, captures),
        Ast::WordBoundary { negated } => {
            let before = position > 0 && is_word_char(input[position - 1]);
            let after = position < input.len() && is_word_char(input[position]);
            ((before != after) != *negated) && continuation(position, captures)
        }
        Ast::Sequence(nodes) => eval_sequence(nodes, 0, input, position, captures, continuation),
        Ast::Alternation(alternatives) => {
            for alternative in alternatives {
                if eval(alternative, input, position, captures.clone(), continuation) {
                    return true;
                }
            }
            false
        }
        Ast::Group { capture, child } => {
            if let Some(index) = capture {
                let index = *index;
                let mut group_captures = captures;
                if index < group_captures.len() {
                    group_captures[index] = Some((position, position));
                }
                eval(child, input, position, group_captures, &mut |end, mut next_captures| {
                    if index < next_captures.len() {
                        next_captures[index] = Some((position, end));
                    }
                    continuation(end, next_captures)
                })
            } else {
                eval(child, input, position, captures, continuation)
            }
        }
        Ast::Lookahead {
            negated,
            behind,
            child,
        } => {
            if *behind {
                if *negated {
                    let exists = (0..=position).rev().any(|start| {
                        eval(child, input, start, captures.clone(), &mut |end, _| {
                            end == position
                        })
                    });
                    !exists && continuation(position, captures)
                } else {
                    for start in (0..=position).rev() {
                        let matched = eval(
                            child,
                            input,
                            start,
                            captures.clone(),
                            &mut |end, next_captures| {
                                end == position && continuation(position, next_captures)
                            },
                        );
                        if matched {
                            return true;
                        }
                    }
                    false
                }
            } else if *negated {
                let exists = eval(child, input, position, captures.clone(), &mut |_, _| true);
                !exists && continuation(position, captures)
            } else {
                eval(child, input, position, captures, &mut |_, next_captures| {
                    continuation(position, next_captures)
                })
            }
        }
        Ast::Repeat {
            child,
            min,
            max,
            greedy,
        } => eval_repeat(child, *min, *max, *greedy, 0, input, position, captures, continuation),
        Ast::BackReference(index) => {
            let captured = captures.get(*index).copied().flatten();
            if let Some((start, end)) = captured {
                let length = end - start;
                if position + length <= input.len() && input[position..position + length] == input[start..end] {
                    continuation(position + length, captures)
                } else {
                    false
                }
            } else {
                continuation(position, captures)
            }
        }
        Ast::NamedBackReference(_) => continuation(position, captures),
        Ast::DecimalEscape { digits, value } => {
            // Group count is not needed for the patterns generated by Melody.
            // Resolve a decimal escape as a legacy octal escape if it was not
            // resolved to a backreference while parsing.
            let _ = value;
            let sequence = decimal_escape_sequence(digits);
            eval_sequence(&sequence, 0, input, position, captures, continuation)
        }
    }
}

fn eval_sequence(
    nodes: &[Ast],
    index: usize,
    input: &[char],
    position: usize,
    captures: Captures,
    continuation: &mut dyn FnMut(usize, Captures) -> bool,
) -> bool {
    if index >= nodes.len() {
        return continuation(position, captures);
    }
    eval(&nodes[index], input, position, captures, &mut |next_position, next_captures| {
        eval_sequence(nodes, index + 1, input, next_position, next_captures, continuation)
    })
}

fn simple_repeat_end(
    child: &Ast,
    input: &[char],
    position: usize,
) -> Option<usize> {
    match child {
        Ast::Char(expected) => {
            if position < input.len() && input[position] as u32 == *expected {
                Some(position + 1)
            } else {
                None
            }
        }
        Ast::Dot => {
            if position < input.len() && !is_line_terminator(input[position] as u32) {
                Some(position + 1)
            } else {
                None
            }
        }
        Ast::Class { negated, items } => {
            if position < input.len() {
                let value = input[position] as u32;
                if items.iter().any(|item| item.matches(value)) != *negated {
                    return Some(position + 1);
                }
            }
            None
        }
        _ => None,
    }
}

fn eval_repeat(
    child: &Ast,
    min: u64,
    max: Option<u64>,
    greedy: bool,
    count: u64,
    input: &[char],
    position: usize,
    captures: Captures,
    continuation: &mut dyn FnMut(usize, Captures) -> bool,
) -> bool {
    // A fast iterative path for one-character atoms.  This covers most
    // quantified literals/classes and avoids recursion proportional to the
    // length of the text being tested.
    if count == 0 && matches!(child, Ast::Char(_) | Ast::Dot | Ast::Class { .. }) {
        let limit = max.unwrap_or(u64::MAX);
        let mut maximum = 0u64;
        let mut current = position;
        while maximum < limit {
            let Some(next) = simple_repeat_end(child, input, current) else {
                break;
            };
            maximum += 1;
            current = next;
        }
        if maximum < min {
            return false;
        }
        if greedy {
            let mut take = maximum;
            loop {
                if continuation(position + take as usize, captures.clone()) {
                    return true;
                }
                if take == min {
                    return false;
                }
                take -= 1;
            }
        } else {
            let mut take = min;
            loop {
                if continuation(position + take as usize, captures.clone()) {
                    return true;
                }
                if take == maximum {
                    return false;
                }
                take += 1;
            }
        }
    }

    let can_repeat = max.map(|maximum| count < maximum).unwrap_or(true);
    if greedy {
        if can_repeat {
            let matched = eval(child, input, position, captures.clone(), &mut |next_position, next_captures| {
                if next_position == position && count >= min {
                    false
                } else {
                    eval_repeat(
                        child,
                        min,
                        max,
                        greedy,
                        count + 1,
                        input,
                        next_position,
                        next_captures,
                        continuation,
                    )
                }
            });
            if matched {
                return true;
            }
        }
        count >= min && continuation(position, captures)
    } else {
        if count >= min && continuation(position, captures.clone()) {
            return true;
        }
        if can_repeat {
            return eval(child, input, position, captures, &mut |next_position, next_captures| {
                if next_position == position && count >= min {
                    false
                } else {
                    eval_repeat(
                        child,
                        min,
                        max,
                        greedy,
                        count + 1,
                        input,
                        next_position,
                        next_captures,
                        continuation,
                    )
                }
            });
        }
        false
    }
}

fn decimal_escape_sequence(digits: &str) -> Vec<Ast> {
    let bytes: Vec<char> = digits.chars().collect();
    let mut result = Vec::new();
    let mut index = 0;
    while index < bytes.len() {
        let first = bytes[index];
        if ('0'..='7').contains(&first) {
            let maximum = if ('0'..='3').contains(&first) { 3 } else { 2 };
            let mut value = first as u32 - '0' as u32;
            let mut taken = 1;
            while taken < maximum
                && index + taken < bytes.len()
                && ('0'..='7').contains(&bytes[index + taken])
            {
                value = value * 8 + (bytes[index + taken] as u32 - '0' as u32);
                taken += 1;
            }
            result.push(Ast::Char(value));
            index += taken;
        } else {
            result.push(Ast::Char(first as u32));
            index += 1;
        }
    }
    result
}

struct RegexParser {
    chars: Vec<char>,
    position: usize,
    group_count: usize,
    group_names: HashMap<String, usize>,
}

struct BracedQuantifier {
    min: u64,
    max: Option<u64>,
    min_text: String,
    max_text: Option<String>,
    end: usize,
}

impl RegexParser {
    fn new(pattern: &str) -> Self {
        RegexParser {
            chars: pattern.chars().collect(),
            position: 0,
            group_count: 0,
            group_names: HashMap::new(),
        }
    }

    fn parse(&mut self) -> Result<Ast, String> {
        let ast = self.parse_disjunction()?;
        if !self.at_end() {
            return Err("unbalanced parenthesis".to_string());
        }
        Ok(self.resolve_decimal_escapes(ast))
    }

    fn resolve_decimal_escapes(&self, ast: Ast) -> Ast {
        match ast {
            Ast::DecimalEscape { digits, value } => {
                if value >= 1 && value <= self.group_count as u64 {
                    Ast::BackReference(value as usize)
                } else {
                    Ast::DecimalEscape { digits, value }
                }
            }
            Ast::Sequence(nodes) => Ast::Sequence(
                nodes
                    .into_iter()
                    .map(|node| self.resolve_decimal_escapes(node))
                    .collect(),
            ),
            Ast::Alternation(nodes) => Ast::Alternation(
                nodes
                    .into_iter()
                    .map(|node| self.resolve_decimal_escapes(node))
                    .collect(),
            ),
            Ast::Group { capture, child } => Ast::Group {
                capture,
                child: Box::new(self.resolve_decimal_escapes(*child)),
            },
            Ast::Lookahead {
                negated,
                behind,
                child,
            } => Ast::Lookahead {
                negated,
                behind,
                child: Box::new(self.resolve_decimal_escapes(*child)),
            },
            Ast::Repeat {
                child,
                min,
                max,
                greedy,
            } => Ast::Repeat {
                child: Box::new(self.resolve_decimal_escapes(*child)),
                min,
                max,
                greedy,
            },
            Ast::NamedBackReference(name) => {
                if let Some(index) = self.group_names.get(&name) {
                    Ast::BackReference(*index)
                } else {
                    // Annex B treats \k as a literal k when there is no
                    // corresponding named group syntax to resolve.  Keep the
                    // original node as an empty match is a closer fallback
                    // than failing compilation for generated patterns.
                    Ast::NamedBackReference(name)
                }
            }
            other => other,
        }
    }

    fn at_end(&self) -> bool {
        self.position >= self.chars.len()
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.position + offset).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let character = self.peek();
        if character.is_some() {
            self.position += 1;
        }
        character
    }

    fn eat(&mut self, expected: char) -> bool {
        if self.peek() == Some(expected) {
            self.position += 1;
            true
        } else {
            false
        }
    }

    fn parse_disjunction(&mut self) -> Result<Ast, String> {
        let mut alternatives = vec![self.parse_alternative()?];
        while self.eat('|') {
            alternatives.push(self.parse_alternative()?);
        }
        if alternatives.len() == 1 {
            Ok(alternatives.pop().unwrap())
        } else {
            Ok(Ast::Alternation(alternatives))
        }
    }

    fn parse_alternative(&mut self) -> Result<Ast, String> {
        let mut terms = Vec::new();
        while let Some(character) = self.peek() {
            if character == '|' || character == ')' {
                break;
            }
            terms.push(self.parse_term()?);
        }
        Ok(Ast::Sequence(terms))
    }

    fn parse_term(&mut self) -> Result<Ast, String> {
        let Some(character) = self.peek() else {
            return Ok(Ast::Empty);
        };
        match character {
            '*' | '+' | '?' => Err("invalid atom character".to_string()),
            '{' if self.scan_braced_quantifier(self.position).is_some() => {
                Err("invalid braced quantifier".to_string())
            }
            '^' => {
                self.position += 1;
                if self.at_quantifier() {
                    return Err("quantifier not allowed here".to_string());
                }
                Ok(Ast::Start)
            }
            '$' => {
                self.position += 1;
                if self.at_quantifier() {
                    return Err("quantifier not allowed here".to_string());
                }
                Ok(Ast::End)
            }
            _ => {
                let atom = self.parse_atom()?;
                self.parse_quantifier(atom)
            }
        }
    }

    fn at_quantifier(&self) -> bool {
        matches!(self.peek(), Some('*' | '+' | '?'))
            || (self.peek() == Some('{') && self.scan_braced_quantifier(self.position).is_some())
    }

    fn parse_quantifier(&mut self, atom: Ast) -> Result<Ast, String> {
        let (min, max) = match self.peek() {
            Some('*') => {
                self.position += 1;
                (0, None)
            }
            Some('+') => {
                self.position += 1;
                (1, None)
            }
            Some('?') => {
                self.position += 1;
                (0, Some(1))
            }
            Some('{') => {
                let Some(braced) = self.scan_braced_quantifier(self.position) else {
                    return Ok(atom);
                };
                if let Some(maximum) = braced.max {
                    if numeric_text_greater(&braced.min_text, braced.max_text.as_deref().unwrap_or("")) {
                        return Err("invalid quantifier".to_string());
                    }
                    let _ = maximum;
                }
                self.position = braced.end;
                (braced.min, braced.max)
            }
            _ => return Ok(atom),
        };
        let greedy = !self.eat('?');
        Ok(Ast::Repeat {
            child: Box::new(atom),
            min,
            max,
            greedy,
        })
    }

    fn scan_braced_quantifier(&self, start: usize) -> Option<BracedQuantifier> {
        if self.chars.get(start) != Some(&'{') {
            return None;
        }
        let mut index = start + 1;
        let min_start = index;
        while self.chars.get(index).is_some_and(|c| c.is_ascii_digit()) {
            index += 1;
        }
        if index == min_start {
            return None;
        }
        let min_text: String = self.chars[min_start..index].iter().collect();
        let min = parse_saturating_u64(&min_text);
        if self.chars.get(index) == Some(&'}') {
            return Some(BracedQuantifier {
                min,
                max: Some(min),
                min_text: min_text.clone(),
                max_text: Some(min_text),
                end: index + 1,
            });
        }
        if self.chars.get(index) != Some(&',') {
            return None;
        }
        index += 1;
        let max_start = index;
        while self.chars.get(index).is_some_and(|c| c.is_ascii_digit()) {
            index += 1;
        }
        if self.chars.get(index) != Some(&'}') {
            return None;
        }
        let (max, max_text) = if index == max_start {
            (None, None)
        } else {
            let text: String = self.chars[max_start..index].iter().collect();
            (Some(parse_saturating_u64(&text)), Some(text))
        };
        Some(BracedQuantifier {
            min,
            max,
            min_text,
            max_text,
            end: index + 1,
        })
    }

    fn parse_atom(&mut self) -> Result<Ast, String> {
        let Some(character) = self.bump() else {
            return Ok(Ast::Empty);
        };
        match character {
            '.' => Ok(Ast::Dot),
            '(' => self.parse_group(),
            '[' => self.parse_class(),
            '\\' => self.parse_escape(false),
            '^' => Ok(Ast::Start),
            '$' => Ok(Ast::End),
            _ => Ok(Ast::Char(character as u32)),
        }
    }

    fn parse_group(&mut self) -> Result<Ast, String> {
        if self.eat('?') {
            match self.peek() {
                Some(':') => {
                    self.position += 1;
                    let child = self.parse_disjunction()?;
                    self.expect_closing_parenthesis()?;
                    Ok(Ast::Group {
                        capture: None,
                        child: Box::new(child),
                    })
                }
                Some('=') => {
                    self.position += 1;
                    let child = self.parse_disjunction()?;
                    self.expect_closing_parenthesis()?;
                    Ok(Ast::Lookahead {
                        negated: false,
                        behind: false,
                        child: Box::new(child),
                    })
                }
                Some('!') => {
                    self.position += 1;
                    let child = self.parse_disjunction()?;
                    self.expect_closing_parenthesis()?;
                    Ok(Ast::Lookahead {
                        negated: true,
                        behind: false,
                        child: Box::new(child),
                    })
                }
                Some('<') => {
                    self.position += 1;
                    if self.eat('=') {
                        let child = self.parse_disjunction()?;
                        self.expect_closing_parenthesis()?;
                        Ok(Ast::Lookahead {
                            negated: false,
                            behind: true,
                            child: Box::new(child),
                        })
                    } else if self.eat('!') {
                        let child = self.parse_disjunction()?;
                        self.expect_closing_parenthesis()?;
                        Ok(Ast::Lookahead {
                            negated: true,
                            behind: true,
                            child: Box::new(child),
                        })
                    } else {
                        let name = self.parse_capture_name()?;
                        if self.group_names.contains_key(&name) {
                            return Err("duplicate capture group name".to_string());
                        }
                        self.group_count += 1;
                        let index = self.group_count;
                        self.group_names.insert(name, index);
                        let child = self.parse_disjunction()?;
                        self.expect_closing_parenthesis()?;
                        Ok(Ast::Group {
                            capture: Some(index),
                            child: Box::new(child),
                        })
                    }
                }
                _ => Err("invalid token at named capture group identifier".to_string()),
            }
        } else {
            self.group_count += 1;
            let index = self.group_count;
            let child = self.parse_disjunction()?;
            self.expect_closing_parenthesis()?;
            Ok(Ast::Group {
                capture: Some(index),
                child: Box::new(child),
            })
        }
    }

    fn expect_closing_parenthesis(&mut self) -> Result<(), String> {
        if self.eat(')') {
            Ok(())
        } else {
            Err("unbalanced parenthesis".to_string())
        }
    }

    fn parse_capture_name(&mut self) -> Result<String, String> {
        let mut name = String::new();
        while let Some(character) = self.peek() {
            if character == '>' {
                self.position += 1;
                if is_valid_capture_name(&name) {
                    return Ok(name);
                }
                return Err("invalid token at named capture group identifier".to_string());
            }
            name.push(character);
            self.position += 1;
        }
        Err("invalid token at named capture group identifier".to_string())
    }

    fn parse_class(&mut self) -> Result<Ast, String> {
        let negated = self.eat('^');
        let mut items = Vec::new();
        while let Some(character) = self.peek() {
            if character == ']' {
                self.position += 1;
                return Ok(Ast::Class { negated, items });
            }
            let first = self.parse_class_atom()?;
            if self.peek() == Some('-')
                && self.peek_at(1).is_some()
                && self.peek_at(1) != Some(']')
            {
                self.position += 1;
                let second = self.parse_class_atom()?;
                if let (Some(start), Some(end)) = (first.is_single(), second.is_single()) {
                    if start > end {
                        return Err(
                            "range values reversed, start char code is greater than end char code."
                                .to_string(),
                        );
                    }
                    items.push(ClassItem::Range(start, end));
                } else {
                    items.push(first);
                    items.push(ClassItem::Single('-' as u32));
                    items.push(second);
                }
            } else {
                items.push(first);
            }
        }
        Err("unbalanced bracket".to_string())
    }

    fn parse_class_atom(&mut self) -> Result<ClassItem, String> {
        let Some(character) = self.peek() else {
            return Err("unbalanced bracket".to_string());
        };
        if character == '\\' {
            self.position += 1;
            match self.parse_escape(true)? {
                Ast::Char(value) => Ok(ClassItem::Single(value)),
                Ast::Class { negated, items } if items.len() == 1 => {
                    let item = items.into_iter().next().unwrap();
                    if negated {
                        Ok(match item {
                            ClassItem::Digit { negated } => ClassItem::Digit { negated: !negated },
                            ClassItem::Word { negated } => ClassItem::Word { negated: !negated },
                            ClassItem::Space { negated } => ClassItem::Space { negated: !negated },
                            other => other,
                        })
                    } else {
                        Ok(item)
                    }
                }
                Ast::DecimalEscape { digits, .. } => {
                    let sequence = decimal_escape_sequence(&digits);
                    if sequence.len() == 1 {
                        if let Ast::Char(value) = sequence[0] {
                            return Ok(ClassItem::Single(value));
                        }
                    }
                    Ok(ClassItem::Single('\\' as u32))
                }
                _ => Ok(ClassItem::Single('\\' as u32)),
            }
        } else {
            self.position += 1;
            Ok(ClassItem::Single(character as u32))
        }
    }

    fn parse_escape(&mut self, in_class: bool) -> Result<Ast, String> {
        let Some(character) = self.bump() else {
            return Err("invalid escape sequence".to_string());
        };
        let result = match character {
            'b' if !in_class => Ast::WordBoundary { negated: false },
            'B' if !in_class => Ast::WordBoundary { negated: true },
            'b' => Ast::Char(0x08),
            'd' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Digit { negated: false }],
            },
            'D' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Digit { negated: true }],
            },
            'w' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Word { negated: false }],
            },
            'W' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Word { negated: true }],
            },
            's' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Space { negated: false }],
            },
            'S' => Ast::Class {
                negated: false,
                items: vec![ClassItem::Space { negated: true }],
            },
            'f' => Ast::Char(0x0c),
            'n' => Ast::Char(0x0a),
            'r' => Ast::Char(0x0d),
            't' => Ast::Char(0x09),
            'v' => Ast::Char(0x0b),
            '0'..='9' => {
                if character == '0' && !self.peek().is_some_and(|c| c.is_ascii_digit()) {
                    Ast::Char(0)
                } else if character == '0' || in_class {
                    // A leading zero is a legacy octal escape (which may
                    // consume following octal digits).  Other digits in a
                    // character class are legacy octal escapes as well.
                    let mut digits = String::new();
                    digits.push(character);
                    let maximum = if ('0'..='3').contains(&character) { 3 } else { 2 };
                    while digits.len() < maximum
                        && self.peek().is_some_and(|c| ('0'..='7').contains(&c))
                    {
                        digits.push(self.bump().unwrap());
                    }
                    let value = u32::from_str_radix(&digits, 8).unwrap_or(0);
                    Ast::Char(value)
                } else {
                    let mut digits = String::new();
                    digits.push(character);
                    while self.peek().is_some_and(|c| c.is_ascii_digit()) {
                        digits.push(self.bump().unwrap());
                    }
                    let value = parse_saturating_u64(&digits);
                    Ast::DecimalEscape { digits, value }
                }
            }
            'x' => {
                if let Some(value) = self.read_hex(2) {
                    Ast::Char(value)
                } else {
                    Ast::Char('x' as u32)
                }
            }
            'u' => {
                if let Some(value) = self.read_unicode_escape()? {
                    Ast::Char(value)
                } else {
                    Ast::Char('u' as u32)
                }
            }
            'c' => {
                if let Some(control) = self.peek() {
                    if control.is_ascii_alphabetic() {
                        self.position += 1;
                        Ast::Char((control as u32) % 32)
                    } else {
                        Ast::Char('c' as u32)
                    }
                } else {
                    Ast::Char('c' as u32)
                }
            }
            'k' if !in_class && self.peek() == Some('<') => {
                self.position += 1;
                let name = self.parse_capture_name().unwrap_or_default();
                Ast::NamedBackReference(name)
            }
            _ => Ast::Char(character as u32),
        };
        Ok(result)
    }

    fn read_hex(&mut self, count: usize) -> Option<u32> {
        let start = self.position;
        let mut value = 0u32;
        for _ in 0..count {
            let character = self.chars.get(self.position)?;
            let digit = character.to_digit(16)?;
            value = value * 16 + digit;
            self.position += 1;
        }
        let _ = start;
        Some(value)
    }

    fn read_unicode_escape(&mut self) -> Result<Option<u32>, String> {
        if self.peek() == Some('{') {
            // In non-Unicode mode \u{...} is not a Unicode code-point
            // escape; leave the braces to be parsed as literal text by
            // treating this simply as an identity escape for u.  The caller
            // only calls this after consuming the u, so restore that point
            // by signalling that no escape was read.
            return Ok(None);
        }
        let saved = self.position;
        let Some(first) = self.read_hex(4) else {
            self.position = saved;
            return Ok(None);
        };
        if (0xd800..=0xdbff).contains(&first) {
            let after_first = self.position;
            if self.peek() == Some('\\') && self.peek_at(1) == Some('u') {
                self.position += 2;
                if let Some(second) = self.read_hex(4) {
                    if (0xdc00..=0xdfff).contains(&second) {
                        return Ok(Some(
                            0x10000 + (((first - 0xd800) << 10) | (second - 0xdc00)),
                        ));
                    }
                }
                self.position = after_first;
            }
        }
        Ok(Some(first))
    }
}

fn parse_saturating_u64(text: &str) -> u64 {
    let mut value = 0u64;
    for character in text.chars() {
        let digit = character as u64 - '0' as u64;
        value = value.saturating_mul(10).saturating_add(digit);
    }
    value
}

fn numeric_text_greater(first: &str, second: &str) -> bool {
    let first = first.trim_start_matches('0');
    let second = second.trim_start_matches('0');
    first.len() > second.len() || (first.len() == second.len() && first > second)
}

fn is_valid_capture_name(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !(first == '_' || first == '$' || first.is_alphabetic()) {
        return false;
    }
    chars.all(|character| {
        character == '_'
            || character == '$'
            || character == '\u{200c}'
            || character == '\u{200d}'
            || character.is_alphanumeric()
    })
}

fn is_ascii_digit(value: u32) -> bool {
    (0x30..=0x39).contains(&value)
}

fn is_word_value(value: u32) -> bool {
    (0x30..=0x39).contains(&value)
        || (0x41..=0x5a).contains(&value)
        || (0x61..=0x7a).contains(&value)
        || value == '_' as u32
}

fn is_word_char(character: char) -> bool {
    is_word_value(character as u32)
}

fn is_space_value(value: u32) -> bool {
    matches!(
        value,
        0x0009
            | 0x000a
            | 0x000b
            | 0x000c
            | 0x000d
            | 0x0020
            | 0x00a0
            | 0x1680
            | 0x2000..=0x200a
            | 0x2028
            | 0x2029
            | 0x202f
            | 0x205f
            | 0x3000
            | 0xfeff
    )
}

fn is_line_terminator(value: u32) -> bool {
    matches!(value, 0x000a | 0x000d | 0x2028 | 0x2029)
}
